MATCH (s:PlantItem {tag: 'P-1-2'}), (t:PlantItem {tag: 'TK-2-2'})
RETURN s.tag AS source_tag, t.tag AS destination_tag,
       EXISTS {
         MATCH p = (s)-[:send_to*0..]->(t)
         WHERE all(n IN nodes(p) WHERE n.tag IS NULL OR n.tag <> 'T-2-1')
       } AS can_flow_without_T_2_1

MATCH (target:PlantItem {tag: "T-2-3"})
MATCH (source:PlantItem)-[:send_to*1..]->(target)
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
